python3 -c "
import json
with open('/app/resources/treasury_bulletin_1950_01.json') as f:
    data = json.load(f)
# Search for any CPI-related keys
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'cpi' in k.lower() or 'price' in k.lower() or 'index' in k.lower():
                print(f'{path}.{k}: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
search(data)
